const read=rel=>JSON.parse(fs.readFileSync(path.join(ROOT,rel),'utf8'));
const writeJson=(rel,value)=>{const full=path.join(ROOT,rel);fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,JSON.stringify(value,null,2)+'\n');};
const writeText=(rel,value)=>{const full=path.join(ROOT,rel);fs.mkdirSync(path.dirname(full),{recursive:true});fs.writeFileSync(full,value.endsWith('\n')?value:value+'\n');};

const model=read(MODEL);
const grammar=read(GRAMMAR);
const plan=read(PLAN);
const refs=TYPES.flatMap(type=>{
  const rel=`data/Civication/mailFamilies/${CATEGORY}/${type}/${ROLE}_${type}.json`;
  const d=read(rel);
  return (d.families||[]).flatMap(f=>(f.mails||[]).map(m=>`${rel}#${m.id}`));
});
if(refs.length!==15||new Set(refs).size!==15)throw new Error(`Expected 15 unique canonical mails, got ${refs.length}/${new Set(refs).size}`);
if(plan.sequence.length!==16)throw new Error('Expected existing 16-step plan');
if(model.related_people.length!==4)throw new Error('Expected four prerequisite scenario actors');
